// Code should be written in Go/Golang
// Write a function to count the most common words in a dictionary.
// Examples:
// >>> count_common(['red','green','black','pink','black','white','black','eyes','white','black','orange','pink','pink','red','red','white','orange','white',"black",'pink','green','green','pink','green','pink','white','orange',"orange",'red'])
// >>> [('pink', 6), ('black', 5), ('white', 5), ('red', 4)]
// >>> count_common(['one', 'two', 'three', 'four', 'five', 'one', 'two', 'one', 'three', 'one'])
// >>> [('one', 4), ('two', 2), ('three', 2), ('four', 1)]
// >>> count_common(['Facebook', 'Apple', 'Amazon', 'Netflix', 'Google', 'Apple', 'Netflix', 'Amazon'])
// >>> [('Apple', 2), ('Amazon', 2), ('Netflix', 2), ('Facebook', 1)]
func count_common (words []string) [][]interface{} {
	var result [][]interface{}
	var count int
	var word string
	var map_words = make(map[string]int)
	for _, word = range words {
		if _, ok := map_words[word]; ok {
			map_words[word] += 1
		} else {
			map_words[word] = 1
		}
	}
	for word, count = range map_words {
		result = append(result, []interface{}{word, count})
	}
	return result
}

func main() {
	var words []string
	var result [][]interface{}
	var json_result []byte
	json_result, _ = json.Marshal(count_common(words))
	json.Unmarshal(json_result, &result)
	for _, word := range result {
		if reflect.TypeOf(word[0]).String() == "string" {
			println(word[0], word[1])
		}
	}
}

