// Code should be written in Go/Golang
// Write a function to convert the given binary number to its decimal equivalent.
// Examples:
// >>> binary_to_decimal(100)
// >>> 4
// >>> binary_to_decimal(1011)
// >>> 11
// >>> binary_to_decimal(1101101)
// >>> 109
func binary_to_decimal (binary int) int {
	var decimal int = 0
	var temp int = binary
	var base int = 1
	for temp > 0 {
		last_digit := temp % 10
		decimal += last_digit * base
		temp = temp / 10
		base = base * 2
	}
	return decimal
}

