		output_array = append(output_array, binary_to_decimal(value))
	}
	expected_output := "[4, 11, 109]"
	output, err := json.Marshal(output_array)
	if err != nil {
		panic(err)
	}
	if reflect.DeepEqual(string(output), expected_output) == true {
		print("Correct")
	} else {
		print("Incorrect")
	}
}

