// >>> 36
func kth_element (arr []int, n int, k int) int {
	if n == 1 {
		return arr[0]
	}
	if k > n {
		return -1
	}
	pivot := arr[0]
	left := []int{}
	right := []int{}
	for i := 1; i < n; i++ {
		if arr[i] < pivot {
			left = append(left, arr[i])
		} else {
			right = append(right, arr[i])
		}
	}
	if k <= len(left) {
		return kth_element(left, len(left), k)
	} else {
		return kth_element(right, len(right), k - len(left) - 1)
	}
}

