// >>> pancake_sort([98, 12, 54, 36, 85])
// >>> [12, 36, 54, 85, 98]
// >>> pancake_sort([41, 42, 32, 12, 23])
// >>> [12, 23, 32, 41, 42]
func pancake_sort (nums []int) []int {
	// Write your code here
	for i := len(nums) - 1; i > 0; i-- {
		maxIndex := findMaxIndex(nums, i)
		if maxIndex != i {
			reverse(nums, maxIndex)
			reverse(nums, i)
		}
	}
	return nums
}

func findMaxIndex(nums []int, i int) int {
	maxIndex := 0
	max := nums[0]
	for j := 1; j <= i; j++ {
		if nums[j] > max {
			max = nums[j]
			maxIndex = j
		}
	}
	return maxIndex
}

func reverse(nums []int, i int) {
	for j := 0; j < i; j++ {
		nums[j], nums[i] = nums[i], nums[j]
		i--
	}
}

