// >>> [7, 11, 19, 25, 33, 45, 78]
// >>> merge_sort([3, 1, 4, 9, 8])
// >>> [1, 3, 4, 8, 9]
func merge_sort (x []int) []int {
	if len(x) <= 1 {
		return x
	}
	mid := len(x) / 2
	left := merge_sort(x[:mid])
	right := merge_sort(x[mid:])
	return merge(left, right)
}

func merge(left, right []int) []int {
	result := make([]int, len(left) + len(right))
	i := 0
	for len(left) > 0 && len(right) > 0 {
		if left[0] < right[0] {
			result[i] = left[0]
			left = left[1:]
		} else {
			result[i] = right[0]
			right = right[1:]
		}
		i++
	}
	for j := 0; j < len(left); j++ {
		result[i] = left[j]
		i++
	}
	for j := 0; j < len(right); j++ {
		result[i] = right[j]
		i++
	}
	return result
}

