// >>> False
// >>> areEquivalent(23,47)
// >>> True
func areEquivalent (num1 int, num2 int) bool {
	var sum1, sum2 int
	for i := 1; i < int(math.Sqrt(float64(num1))); i++ {
		if num1 % i == 0 {
			sum1 += i
			sum1 += num1 / i
		}
	}
	for i := 1; i < int(math.Sqrt(float64(num2))); i++ {
		if num2 % i == 0 {
			sum2 += i
			sum2 += num2 / i
		}
	}
	return sum1 == sum2
}

