	json.Unmarshal([]byte(`{"name": "Wednesday", "age": 6, "gender": "female"}`), &obj)
	recursivePrint(obj, "")
}

func recursivePrint(obj interface{}, indent string) {
	switch reflect.TypeOf(obj).Kind() {
	case reflect.Map:
		v := reflect.ValueOf(obj)
		keys := v.MapKeys()
		for _, key := range keys {
			val := v.MapIndex(key)
			if reflect.TypeOf(val.Interface()).Kind() == reflect.Map {
				recursivePrint(val.Interface(), indent+"\t")
			} else {
				println(indent + key.String() + ":", val.Interface())
			}
		}
	}
}

