// >>> 2
// >>> swap_count("[[][]]")
// >>> 0
// >>> swap_count("[[][]]][")
// >>> 1
func swap_count (s string) int {
	var stack []rune
	for _, r := range s {
		if r == '[' {
			stack = append(stack, r)
		} else if r == ']' {
			if len(stack) == 0 {
				stack = append(stack, r)
			} else {
				stack = stack[:len(stack)-1]
			}
		}
	}
	return len(stack)
}

