// >>> 'No'
func check_Triangle (x1 int, y1 int, x2 int, y2 int, x3 int, y3 int) string {
	var a, b, c float64
	a = distance(x1, y1, x2, y2)
	b = distance(x2, y2, x3, y3)
	c = distance(x3, y3, x1, y1)
	if a + b > c && a + c > b && b + c > a {
		return "Yes"
	}
	return "No"
}

func distance(x1 int, y1 int, x2 int, y2 int) float64 {
	return float64(sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1)))
}

func sqrt(x int) int {
	z := x / 2
	for z*z < x {
		z -= (z*z - x) / (2 * z)
	}
	return z
}

