// Code should be written in Go/Golang
// Write a golang function to find the sum of the largest and smallest value in a given array.
// Examples:
// >>> big_sum([1,2,3])
// >>> 4
// >>> big_sum([-1,2,3,4])
// >>> 3
// >>> big_sum([2,3,6])
// >>> 8
func big_sum (nums []int) int {
	var max int
	var min int
	for i := 0; i < len(nums); i++ {
		if i == 0 {
			max = nums[i]
			min = nums[i]
		}
		if nums[i] > max {
			max = nums[i]
		}
		if nums[i] < min {
			min = nums[i]
		}
	}
	return max + min
}

func main() {
	var nums []int
	var result int
	nums = []int{1,2,3}
	result = big_sum(nums)
	json.NewEncoder(reflect.ValueOf(result).Interface()).Encode(result)
}

