// Code should be written in Go/Golang
// Write a golang function to find the first natural number whose factorial is divisible by x.
// Examples:
// >>> first_Factorial_Divisible_Number(10)
// >>> 5
// >>> first_Factorial_Divisible_Number(15)
// >>> 5
// >>> first_Factorial_Divisible_Number(5)
// >>> 4
func first_Factorial_Divisible_Number (x int) int {
	var i int
	for i = 1; i < x; i++ {
		if x % factorial(i) == 0 {
			break
		}
	}
	return i
}

func factorial(x int) int {
	if x == 0 {
		return 1
	}
	return x * factorial(x - 1)
}

