// Write a function to compute binomial probability for the given number.
// Examples:
// >>> binomial_probability(10, 5, 1.0/3)
// >>> 0.13656454808718185
// >>> binomial_probability(11, 6, 2.0/4)
// >>> 0.2255859375
// >>> binomial_probability(12, 7, 3.0/5)
// >>> 0.227030335488
func binomial_probability (n int, k int, p float64) float64 {
	if n < 0 || k < 0 || k > n {
		return 0
	}
	if p < 0 || p > 1 {
		return 0
	}
	if k == 0 || k == n {
		return 1
	}
	return (1 - p) * binomial_probability(n - 1, k, p) + p * binomial_probability(n - 1, k - 1, p)
}

