// >>> True
// >>> binary_search([11, 13, 14, 19, 22, 36], 23)
// >>> False
func binary_search (item_list []int, item int) bool {
	var low int = 0
	var high int = len(item_list) - 1
	for low <= high {
		var mid int = (low + high) / 2
		if item_list[mid] == item {
			return true
		} else if item_list[mid] < item {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}
	return false
}

