// Code should be written in Go/Golang
// Write a function to find the lcm of the given array elements.
// Examples:
// >>> get_lcm([2, 7, 3, 9, 4])
// >>> 252
// >>> get_lcm([1, 2, 8, 3])
// >>> 24
// >>> get_lcm([3, 8, 4, 10, 5])
// >>> 120
func get_lcm (l []int) int {
	var lcm int
	lcm = 1
	for _, v := range l {
		lcm = lcm * v / gcd(lcm, v)
	}
	return lcm
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

